import re
from datetime import datetime, timedelta, timezone
from fractions import Fraction

_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)
_TIME = re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.([0-9]+))?"
    r"(Z|[+-][0-9]{2}:[0-9]{2})\Z"
)
_LEGACY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2}):([0-9]{2})\Z")


def instant(t: datetime) -> Fraction:
    """An aware time as exact seconds since the epoch."""
    d = t - _EPOCH
    return Fraction(d.days * 86400 + d.seconds) + Fraction(d.microseconds, 10**6)


def parse_data_time(text, legacy: bool = False):
    """The instant (exact seconds) of a time of data.md section 2, or None when `text` is not one.

    `legacy` also accepts the release 1.2 form `YYYY-MM-DD HH:MM:SS`, which is UTC.
    """
    if not isinstance(text, str):
        return None
    m = _TIME.match(text)
    try:
        if m:
            y, mo, d, h, mi, s = (int(g) for g in m.groups()[:6])
            frac = Fraction(int(m.group(7)), 10 ** len(m.group(7))) if m.group(7) else Fraction(0)
            zone = m.group(8)
            if zone == "Z":
                tz = timezone.utc
            else:
                oh, om = int(zone[1:3]), int(zone[4:6])
                if om > 59:
                    return None
                off = timedelta(hours=oh, minutes=om)
                tz = timezone(off if zone[0] == "+" else -off)
            return instant(datetime(y, mo, d, h, mi, s, tzinfo=tz)) + frac
        if legacy:
            m = _LEGACY.match(text)
            if m:
                y, mo, d, h, mi, s = (int(g) for g in m.groups())
                return instant(datetime(y, mo, d, h, mi, s, tzinfo=timezone.utc))
    except (ValueError, OverflowError):
        return None
    return None

