"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None  # bytes; None is off
    max_age: int | None = None  # seconds; None is off
    naming: str = "numbered"
    offset: timedelta = timedelta(0)
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_AGE = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_NUMBER = re.compile(r"[0-9]+\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}
_SECONDS = {"m": 60, "h": 3600, "d": 86400}


def _bad(msg: str):
    raise DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        _bad(f"bad size {v!r}")
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _age(v):
    if v == "off":
        return None
    m = _AGE.match(v)
    if not m:
        _bad(f"bad duration {v!r}")
    return int(m.group(1)) * _SECONDS[m.group(2)]


def _naming(v):
    if v not in ("numbered", "dated"):
        _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        _bad(f"bad offset {v!r}")
    d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return d if m.group(1) == "+" else -d


def _count(minimum):
    def parse(v):
        if not _NUMBER.match(v) or int(v) < minimum:
            _bad(f"bad number {v!r}")
        return int(v)

    return parse


def _keep_days(v):
    return None if v == "off" else _count(1)(v)


_KEYS = {
    "max_size": _size,
    "max_age": _age,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self._defaults = defaults
        self._sections = sections

    @property
    def names(self) -> set[str]:
        return set(self._sections)

    def settings(self, name: str) -> Settings:
        values = dict(self._defaults)
        values.update(self._sections.get(name, {}))
        return replace(Settings(), **values)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    defaults: dict = {}
    sections: dict = {}
    current = None
    seen_defaults = False
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad section line {line!r}")
            title = line[1:-1]
            if title == "defaults":
                if seen_defaults:
                    _bad("section [defaults] twice")
                seen_defaults = True
                current = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    _bad(f"section {name} twice")
                current = sections[name] = {}
            else:
                _bad(f"unknown section {title!r}")
            continue
        if current is None or "=" not in line:
            _bad(f"bad line {line!r}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in _KEYS:
            _bad(f"unknown key {key!r}")
        if key in current:
            _bad(f"key {key} twice")
        current[key] = _KEYS[key](value)
    return Policy(defaults, sections)

"""The rotate command (docs/rotate.md)."""

import gzip
import os
import re
import shutil
from dataclasses import dataclass
from datetime import date, timezone
from pathlib import Path

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused

_DAY = r"([0-9]{4})-([0-9]{2})-([0-9]{2})"


@dataclass
class Archive:
    name: str  # name before the run; for a new archive the plain name it is made as
    gz: bool
    order: tuple  # greater is newer
    day: date | None = None
    k: int = 1
    new: bool = False
    time_text: str | None = None  # the time to write to state.json
    time: object = None  # the same, as an instant
    final: str = ""
    compress: bool = False


def _archives(data: Path, name: str, naming: str) -> list[Archive]:
    """The archives of a stream, newest first. Two in one place are a data error."""
    d = streams.logs_dir(data)
    found: list[Archive] = []
    if not d.is_dir():
        return found
    esc = re.escape(name)
    if naming == "numbered":
        rx = re.compile(rf"{esc}\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(rf"{esc}\.log\.{_DAY}(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")
    for p in d.iterdir():
        m = rx.match(p.name)
        if not m or not p.is_file():
            continue
        if naming == "numbered":
            found.append(Archive(p.name, bool(m.group(2)), (-int(m.group(1)),)))
        else:
            try:
                day = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            except ValueError:
                continue
            k = int(m.group(4)) if m.group(4) else 1
            found.append(Archive(p.name, bool(m.group(5)), (day.toordinal(), k), day=day, k=k))
    places = set()
    for a in found:
        if a.order in places:
            raise DataError("archives", f"{name}: two archives in the same place")
        places.add(a.order)
    found.sort(key=lambda a: a.order, reverse=True)
    return found


def _check_state(doc: dict, existing: set[str]) -> None:
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and dates.parse_data_time(entry["opened"], legacy=True) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for t in arch.values():
                if dates.parse_data_time(t, legacy=True) is None:
                    raise DataError("state", f"{name}: bad archive time")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int):
                raise DataError("state", f"{name}: rotations is not a whole number")


def _first_line_time(path: Path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", "replace").rstrip("\r\n")
    return dates.parse_data_time(text.split(" ", 1)[0])


@dataclass
class Plan:
    name: str
    what: str
    rotated: bool
    entry: dict
    remaining: list
    removed: list
    old_active: Path | None = None


def _plan_stream(ctx, name, pol, force, now_i) -> Plan:
    cfg = pol.settings(name)
    entry = ctx.state["streams"].get(name, {})
    archives = _archives(ctx.data, name, cfg.naming)
    active = streams.log_path(ctx.data, name)

    if not active.is_file():
        what = "no log"
    elif active.stat().st_size == 0:
        what = "empty"
    elif force:
        what = "forced"
    elif cfg.max_size is not None and active.stat().st_size >= cfg.max_size:
        what = "size"
    else:
        what = "not due"
        if cfg.max_age is not None:
            if "opened" in entry:
                opened = dates.parse_data_time(entry["opened"], legacy=True)
            else:
                opened = _first_line_time(active)
            if opened is not None and now_i - opened >= cfg.max_age:
                what = "age"
    rotated = what in ("forced", "size", "age")

    for a in archives:
        t = entry.get("archives", {}).get(a.name)
        if t is not None:
            a.time_text = t
            a.time = dates.parse_data_time(t, legacy=True)

    stamp = dates.stamp(ctx.now)
    if rotated:
        if cfg.naming == "numbered":
            new = Archive(f"{name}.log.1", False, (1,), new=True)
            archives.insert(0, new)
        else:
            local = ctx.now.astimezone(timezone(cfg.offset))
            day = date(local.year, local.month, local.day)
            same = [a.k for a in archives if a.day == day]
            k = max(same) + 1 if same else 1
            base = f"{name}.log.{day.year:04d}-{day.month:02d}-{day.day:02d}"
            new = Archive(base if k == 1 else f"{base}.{k}", False, (day.toordinal(), k),
                          day=day, k=k, new=True)
            archives.append(new)
            archives.sort(key=lambda a: a.order, reverse=True)
        new.time_text = stamp
        new.time = now_i

    remaining, removed = [], []
    for pos, a in enumerate(archives, 1):
        drop = pos > cfg.keep
        if not drop and cfg.keep_days is not None and a.time is not None:
            drop = now_i - a.time >= cfg.keep_days * 86400
        (removed if drop else remaining).append(a)

    for j, a in enumerate(remaining, 1):
        a.compress = j > cfg.compress_after and not a.gz
        gz = a.gz or a.compress
        if cfg.naming == "numbered":
            a.final = f"{name}.log.{j}" + (".gz" if gz else "")
        else:
            a.final = a.name + (".gz" if a.compress else "")

    new_entry = {}
    if rotated:
        new_entry["opened"] = stamp
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_entry["archives"] = {a.final: a.time_text for a in remaining if a.time_text is not None}
    return Plan(name, what, rotated, new_entry, remaining, removed, active if rotated else None)


def _output(plan: Plan) -> list[str]:
    head = "rotate (forced)" if plan.what == "forced" else f"rotate ({plan.what})" if plan.rotated else plan.what
    lines = [f"{plan.name}: {head}"]
    for a in plan.remaining:
        if a.new:
            lines.append(f"  new {a.final}")
        elif a.final != a.name:
            lines.append(f"  {a.final} <- {a.name}")
        else:
            lines.append(f"  {a.final}")
    for a in plan.removed:
        lines.append(f"  remove {a.name}")
    return lines


def _gzip(src: Path, dst: Path) -> None:
    with src.open("rb") as fin, dst.open("wb") as raw:
        with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as gz:
            shutil.copyfileobj(fin, gz)


def _apply(ctx, plan: Plan) -> None:
    logs = streams.logs_dir(ctx.data)
    taken = {p.name for p in logs.iterdir()} if logs.is_dir() else set()
    moves = []  # (tmp path, final path)
    for i, a in enumerate(plan.remaining):
        if not a.new and a.final == a.name:
            continue
        tmp = f".logkeep-{plan.name}-{i}.tmp"
        while tmp in taken:
            tmp += "x"
        taken.add(tmp)
        tmp_p = logs / tmp
        src = plan.old_active if a.new else logs / a.name
        if a.compress:
            _gzip(src, tmp_p)
            if not a.new:
                src.unlink()
        else:
            os.replace(src, tmp_p)
        moves.append((tmp_p, logs / a.final))
    for a in plan.removed:
        if a.new:
            plan.old_active.write_bytes(b"")  # made and removed at once: the content goes
        else:
            (logs / a.name).unlink()
    if plan.rotated:
        plan.old_active.write_bytes(b"")
    for tmp_p, final_p in moves:
        os.replace(tmp_p, final_p)


def run(ctx, force: bool, dry_run: bool, names: list[str]) -> list[str]:
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.names
    _check_state(doc, existing)
    chosen = sorted(set(names)) if names else sorted(existing)
    for n in chosen:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")
    now_i = dates.instant(ctx.now)
    plans = [_plan_stream(ctx, n, pol, force, now_i) for n in chosen]

    out: list[str] = []
    rotated = removed = compressed = 0
    for p in plans:
        out.extend(_output(p))
        rotated += p.rotated
        removed += len(p.removed)
        compressed += sum(a.compress for a in p.remaining)
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    for p in plans:
        _apply(ctx, p)
        doc["streams"][p.name] = p.entry
    state_mod.save(ctx.state_path, doc)
    return out

